//! `timed` (`/system/bin/timed`): the time-of-day service (issue #369).
//!
//! * It registers [`api::NAME`] and serves `os.lazy.timed.v1`
//!   (`idl/timed.midl`, generated by `midlc`): `Now`, `GetZone`, `SetZone` and
//!   the privileged `SetTime`.
//! * UTC comes from the kernel wall clock (native syscall 24); the zone comes
//!   from `confd` (`sys/time/zone`, UTC when unset) and follows its change
//!   notifications. Zone and DST maths live in `libs/timed` (`timezone`).
//! * Each minute it publishes the retained `time/tick` event
//!   (`os.lazy.timed.v1`'s `Tick`) on the central broker.
//!
//! `demo=1` (boot evidence) writes a zone straight into `confd` and waits for
//! the change notification to move the service, printing `TIMED:DEMO:PASS`.
//! Other boot lines: `TIMED:READY`, `TIMED:TICK:PASS`.

#![no_std]
#![no_main]

extern crate alloc;

use alloc::format;
use core::panic::PanicInfo;

use user::messenger::timed as api;
use user::messenger::{self, errno, registry, services, wait, Error};
use user::sys;

#[path = "timed/demo.rs"]
mod demo;
#[path = "timed/handler.rs"]
mod handler;
#[path = "timed/state.rs"]
mod state;

use state::{now, State};

/// How often the `demo=1` evidence steps while it runs (PIT ticks, 100 Hz).
/// Otherwise the service parks until a request, a `confd` change (its watch's
/// doorbell) or the next minute tick.
const DEMO_TICKS: u64 = 20;

#[no_mangle]
pub extern "C" fn _start() -> ! {
    sys::write_str("timed: time-of-day service (issue #369)\n");
    if let Err(error) = run() {
        sys::write_str("timed: fatal: ");
        sys::write_str(error.message());
        sys::write_str("\n");
        sys::exit(1);
    }
    sys::exit(0)
}

fn run() -> messenger::Result<()> {
    let (published, server) = messenger::create_pair()?;
    registry::register(api::NAME, &published, &[api::INTERFACE], 0)?;
    sys::write_str(&format!(
        "TIMED:READY unix={} interface={:#x}\n",
        now().0,
        api::INTERFACE
    ));
    // Serving: what waits for this service may start (init.Ready, P7.3).
    user::messenger::services::init::notify_ready();

    let mut state = State::new();
    let mut demo = demo::Demo::from_args();
    // One receive buffer for the life of the service (the heap never reclaims
    // per-call buffers).
    let mut buffer = alloc::vec![0u8; messenger::DEFAULT_BUFFER];
    let mut announced = false;
    let mut rung = false;
    loop {
        housekeeping(&mut state, &mut demo, &mut announced, rung);
        let deadline = [
            state.next_wake(),
            demo.running().then(|| sys::clock() + DEMO_TICKS),
        ]
        .into_iter()
        .flatten()
        .min();
        let ready = match state.bell() {
            Some(bell) => wait::wait_any(&[server, bell], 0, deadline),
            None => wait::wait_any(&[server], 0, deadline),
        };
        let ready = match ready {
            Ok(ready) => ready,
            Err(Error::Errno(code)) if code == -errno::ETIMEDOUT => 0,
            Err(error) => return Err(error),
        };
        rung = ready & 0b10 != 0;
        if ready & 1 == 0 {
            continue;
        }
        match server.recv_with(&mut buffer, Some(messenger::EXPIRED_DEADLINE)) {
            Ok(message) => {
                let reply = handler::dispatch(&mut state, &message).unwrap_or_else(|error| {
                    services::error_reply(message.interface_id(), message.method(), error)
                });
                if let Some(txn) = message.txn {
                    server.reply_or_drop(txn, &reply)?;
                }
            }
            Err(Error::Errno(code)) if code == -errno::ETIMEDOUT => {}
            Err(error) => return Err(error),
        }
    }
}

/// Zone sync, a rung change notification, the minute tick and the demo,
/// once per wakeup.
fn housekeeping(state: &mut State, demo: &mut demo::Demo, announced: &mut bool, rung: bool) {
    let mut changed = state.sync_zone();
    changed |= state.poll_changes(rung);
    if changed {
        sys::write_str(&format!("TIMED:ZONE zone={}\n", state.zone.name));
        // A zone change must reach `time/tick` subscribers promptly.
        state.next_tick = 0;
    }
    let (unix, _) = now();
    state.publish_if_due(unix);
    if state.announced && !*announced {
        *announced = true;
        let local = state.local(unix);
        sys::write_str(&format!(
            "TIMED:TICK:PASS unix={unix} offset={} zone={}\n",
            local.offset, state.zone.name
        ));
    }
    demo.step(state);
}

#[panic_handler]
fn panic(_info: &PanicInfo) -> ! {
    sys::exit(1)
}
